From d4597c828e65032393192f032f44eb6c99f5b0b3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:55:39 +0100
Subject: [PATCH] containments/desktop: Keep rename field clicks from reaching
 the icons

Clicking the part of a rename field covering the icon below selected
that icon, since the field was a child of the mouse listener that sees
all its children's clicks. Create it outside and drop old workarounds.

BUG: 517584
---
 .../desktop/package/contents/ui/FolderView.qml      | 13 +++----------
 1 file changed, 3 insertions(+), 10 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..55b1e1e98e 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -74,7 +74,7 @@ FocusScope {
             }

             if (!main.editor) {
-                editor = editorComponent.createObject(listener);
+                editor = editorComponent.createObject(main);
             }

             main.editor.targetItem = gridView.currentItem;
@@ -237,12 +237,6 @@ FocusScope {
                 return;
             }

-            // Ignore clicks if main.editor is enabled and we click on that
-            // BUG:494558
-            if (main.editor && childAt(mouse.x, mouse.y) === main.editor) {
-                return;
-            }
-
             scrollArea.focus = true;

             if (mouse.buttons & Qt.BackButton) {
@@ -250,7 +244,7 @@ FocusScope {
                 return;
             }

-            if (main.editor && childAt(mouse.x, mouse.y) !== main.editor) {
+            if (main.editor) {
                 main.editor.commit();
             }

@@ -356,8 +350,7 @@ FocusScope {
         onClicked: mouse => {
             clearPressState();

-            if (mouse.button === Qt.RightButton ||
-                (main.editor && childAt(mouse.x, mouse.y) === main.editor)) {
+            if (mouse.button === Qt.RightButton) {
                 return;
             }

